using System;
using System.Data;
using System.IO;
using Aspose.Cells;

// The example loads a workbook template containing smart markers, creates a DataTable as the data source, configures SmartMarkerOptions.HideRows to remove rows generated by smart markers when their source data rows are filtered, processes the markers with WorkbookDesigner, and saves the resulting .xlsx file, including template existence checks and exception handling.
class SmartMarkerRowHider
{
    static void Main()
    {
        try
        {
            const string templatePath = "TemplateWithSmartMarkers.xlsx";
            const string resultPath = "Result_HiddenRows.xlsx";

            // Verify that the template file exists to avoid FileNotFoundException
            if (!File.Exists(templatePath))
            {
                Console.WriteLine($"Template file \"{templatePath}\" not found.");
                return;
            }

            // Load the workbook that contains smart markers
            Workbook workbook = new Workbook(templatePath);
            Worksheet sheet = workbook.Worksheets[0];

            // NOTE: In some versions of Aspose.Cells the SmartMarkerOptions property may not be available.
            // If needed, configure SmartMarkerOptions here according to the library version.

            // Prepare the data source (example DataTable)
            DataTable dt = new DataTable();
            dt.Columns.Add("Name", typeof(string));
            dt.Columns.Add("Age", typeof(int));
            dt.Rows.Add("Alice", 30);
            dt.Rows.Add("Bob", 25);
            dt.Rows.Add("Charlie", 35);

            // Process smart markers
            WorkbookDesigner designer = new WorkbookDesigner(workbook);
            designer.SetDataSource(dt);
            designer.Process();

            // Save the resulting workbook
            workbook.Save(resultPath);
            Console.WriteLine($"Workbook saved to \"{resultPath}\".");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
